// Hebrew description of a filter set, written by code: the meaning of a learned concept, shown to the
// buyer as an assumption. Never generated by the model, so it always says exactly what the filters do.

const NIS = (v) => (v >= 1000000 ? `${Math.round(v / 100000) / 10} מיליון ₪` : `${Math.round(v / 1000)} אלף ₪`);
const FEATURES = {
    requireParking: 'חניה',
    requireElevator: 'מעלית',
    requireSafeRoom: 'ממ״ד',
    requireBalcony: 'מרפסת'
};
const range = (min, max, unit) => {
    if (min != null && max != null) return `${min}–${max} ${unit}`;
    if (min != null) return `${min} ${unit} לפחות`;
    if (max != null) return `עד ${max} ${unit}`;
    return null;
};

function describeFilters(f) {
    const parts = [];
    if (f.purpose === 'live') parts.push('למגורים');
    if (f.purpose === 'invest') parts.push('להשקעה');
    if (f.propertyTypes?.length) parts.push(f.propertyTypes.join(' או '));
    const rooms = range(f.roomsMin, f.roomsMax, 'חדרים');
    if (rooms) parts.push(rooms);
    const size = range(f.sizeMin, f.sizeMax, 'מ״ר');
    if (size) parts.push(size);
    if (f.cities?.length) parts.push(`ב${f.cities.join(', ')}`);
    if (f.neighborhoods?.length) parts.push(`בשכונות ${f.neighborhoods.join(', ')}`);
    const features = Object.entries(FEATURES).filter(([k]) => f[k] === true).map(([, v]) => v);
    if (features.length) parts.push(`עם ${features.join(', ')} (חובה)`);
    if (f.priceMax != null) parts.push(`עד ${NIS(f.priceMax)}`);
    return parts.join(', ');
}

module.exports = { describeFilters };
